const movementCodes = new Map([
  ['ArrowUp', 'arrowup'], ['ArrowDown', 'arrowdown'],
  ['ArrowLeft', 'arrowleft'], ['ArrowRight', 'arrowright'],
  ['KeyW', 'w'], ['KeyA', 'a'], ['KeyS', 's'], ['KeyD', 'd'],
  ['KeyQ', 'q'], ['KeyE', 'e'],
]);
const movementKeys = new Set(movementCodes.values());

export function bindExhibitionKeyboard(root, { setKey, releaseKeys, enabled }, win = window, doc = document) {
  const held = new Map();
  const identity = event => event.code || event.key?.toLowerCase();
  const action = event => movementCodes.get(event.code) || (movementKeys.has(event.key?.toLowerCase()) ? event.key.toLowerCase() : null);
  const blockedTarget = target => !root.contains(target) || target.closest?.('dialog') !== root ||
    target.isContentEditable || target.closest?.('input, textarea, select, [role="slider"], [role="textbox"], [data-exhibition-keyboard="native"]');

  function clear() {
    for (const key of held.values()) setKey(key, false);
    held.clear();
    releaseKeys();
  }
  function down(event) {
    if (event.metaKey || event.ctrlKey || event.altKey || event.isComposing) { clear(); return; }
    if (!enabled() || blockedTarget(event.target)) { clear(); return; }
    const key = action(event), id = identity(event);
    if (!key || event.defaultPrevented) return;
    event.preventDefault();
    event.stopPropagation();
    // Walking belongs to the scene. A button that was clicked before walking
    // must not acquire a keyboard focus ring on the first direction key.
    // Tab and editing controls keep their normal focus behaviour.
    const scene = root.querySelector?.('[data-exhibition-keyboard-focus]') || root;
    if (doc.activeElement !== scene) scene.focus({ preventScroll: true });
    // A held key must be pressed afresh after a menu, window switch or guided
    // navigation. Auto-repeat must not restart a cancelled walk.
    if (held.has(id) || event.repeat) return;
    held.set(id, key);
    setKey(key, true);
  }
  function up(event) {
    const id = identity(event), key = held.get(id);
    if (!key) return;
    held.delete(id);
    setKey(key, false);
  }
  function visibility() { if (doc.hidden) clear(); }
  function focus(event) { if (blockedTarget(event.target)) clear(); }
  function pointer(event) {
    if (blockedTarget(event.target) || event.target.closest?.('button, a, [role="button"]')) clear();
  }
  root.addEventListener('keydown', down);
  // Focus can leave the dialog when a reading control is replaced. Capture
  // release at the window, including releases intercepted by nested controls.
  win.addEventListener('keyup', up, true);
  win.addEventListener('blur', clear);
  doc.addEventListener('visibilitychange', visibility);
  doc.addEventListener('focusin', focus, true);
  doc.addEventListener('pointerdown', pointer, true);
  return {
    clear,
    dispose() {
      clear();
      root.removeEventListener('keydown', down);
      win.removeEventListener('keyup', up, true);
      win.removeEventListener('blur', clear);
      doc.removeEventListener('visibilitychange', visibility);
      doc.removeEventListener('focusin', focus, true);
      doc.removeEventListener('pointerdown', pointer, true);
    },
  };
}
